using System;using System.Linq;using System.IO;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json.Linq;
public static class BRRefine {
 const string E="Assets/Afrer_Seconds/05.Model/Environment/B2/";
 public static object Inspect(){var g=GameObject.Find("B2_C01_MachineryConsole_Visual");return g.GetComponentsInChildren<Renderer>().Select(r=>new{r.name,materials=r.sharedMaterials.Select(m=>new{m.name,shader=m.shader.name,emission=m.HasProperty("_EmissionColor")?m.GetColor("_EmissionColor").ToString():"",keywords=m.shaderKeywords,texture=m.HasProperty("_EmissionMap")?AssetDatabase.GetAssetPath(m.GetTexture("_EmissionMap")):""}).ToArray()}).ToArray();}
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_B2_Circular.unity"))throw new Exception("Saved B2 required");
 for(int i=1;i<=2;i++){var m=AssetDatabase.LoadAssetAtPath<Material>(E+"Materials/BR_Display_"+i.ToString("00")+".mat");m.SetColor("_EmissionColor",Color.white*1.4f);m.EnableKeyword("_EMISSION");m.globalIlluminationFlags=MaterialGlobalIlluminationFlags.RealtimeEmissive;EditorUtility.SetDirty(m);}
 // Remove obsolete 3m expansion-strip geometry; the new concrete has its own saw joints.
 var f=GameObject.Find("B2_FloorDetails").GetComponent<MeshFilter>();var mesh=f.sharedMesh;var vs=mesh.vertices;var mats=f.GetComponent<MeshRenderer>().sharedMaterials;int removed=0;for(int sub=0;sub<mats.Length;sub++)if(mats[sub].name=="BCM_Dark"){var old=mesh.GetTriangles(sub);var keep=new System.Collections.Generic.List<int>();for(int i=0;i<old.Length;i+=3){var v=new[]{vs[old[i]],vs[old[i+1]],vs[old[i+2]]};bool joint=new float[]{-6,-3,0,3,6}.Any(z=>v.All(p=>Mathf.Abs(p.z-z)<.008f))&&v.Any(p=>Mathf.Abs(p.x)>5);if(joint)removed++;else{keep.Add(old[i]);keep.Add(old[i+1]);keep.Add(old[i+2]);}}mesh.SetTriangles(keep,sub);}EditorUtility.SetDirty(mesh);
 var cart=GameObject.Find("B2_C02_Ops_PartsStaging_14");cart.transform.localRotation=Quaternion.Euler(0,180,0);if(PrefabUtility.IsPartOfPrefabInstance(cart))PrefabUtility.RecordPrefabInstancePropertyModifications(cart.transform);string pp=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/B2_SurfaceRefinement/plan.json"));var plan=JObject.Parse(File.ReadAllText(pp));plan["placements"].Single(p=>(string)p["name"]==cart.name)["yaw"]=180;File.WriteAllText(pp,plan.ToString());AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);return new{removedJointTriangles=removed};}
}
